package com.oea.engine.graphics

import com.oea.engine.OeaEngine
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.nio.charset.StandardCharsets

/**
 * Loads the compact `.oeam` weapon meshes generated by
 * `tools/tripo/weapons_to_oeam.py`. The format is header + 12-float vertices
 * (position, normal, uv, linear RGBA) + u32 indices — exactly [Mesh]'s vertex
 * layout — so no parser or conversion happens on the game thread beyond a
 * single buffer read.
 */
object WeaponAssetLoader {
    private const val MAX_VERTICES = 20_000
    private const val MAX_INDICES = 60_000

    fun fromAssets(name: String): Mesh? = runCatching {
        val bytes = OeaEngine.context.assets.open("weapons/${name.lowercase()}.oeam").use { it.readBytes() }
        if (bytes.size < 12 || String(bytes, 0, 4, StandardCharsets.US_ASCII) != "OEAM") error("bad weapon asset")
        val buf = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN)
        buf.position(4)
        val version = buf.short.toInt()
        val vertices = buf.short.toInt() and 0xFFFF
        val indices = buf.int
        if (version != 1 || vertices <= 0 || vertices > MAX_VERTICES || indices <= 0 || indices > MAX_INDICES) {
            error("unsupported weapon asset $name")
        }
        if (bytes.size < 12 + vertices * 48 + indices * 4) error("truncated weapon asset $name")
        val v = FloatArray(vertices * Mesh.STRIDE)
        for (i in v.indices) v[i] = buf.float
        val idx = IntArray(indices) { buf.int }
        Mesh(v, idx)
    }.getOrNull()
}
